import React, { useState, useEffect, useContext } from 'react';
import { observer } from 'mobx-react-lite';
import { Context } from '../index';
import { Modal, Button, ListGroup, Form, Row, Col, Badge, Spinner } from 'react-bootstrap';
import { http } from '../http';
import '../css/MessageModal.css';

const MessageModal = observer(() => {
    const { message, user } = useContext(Context);
    const [newMessage, setNewMessage] = useState('');
    const [loading, setLoading] = useState(false);
    const [chatsLoading, setChatsLoading] = useState(false);

    useEffect(() => {
        if (message.isModalOpen && user.isAuth) {
            loadChats();
        }
    }, [message.isModalOpen, user.isAuth]);

    const loadChats = async () => {
        setChatsLoading(true);
        try {
            const response = await http.get(`/api/message/chats/${user.user.id}`);
            message.setChats(response.data);
            
            // Подсчет непрочитанных сообщений (можно доработать на сервере)
            const unreadCount = response.data.reduce((total, chat) => total + (chat.unreadCount || 0), 0);
            message.setUnreadCount(unreadCount);
        } catch (error) {
            console.error('Ошибка при загрузке чатов:', error);
        } finally {
            setChatsLoading(false);
        }
    };

    const loadMessages = async (otherUser, product = null) => {
        try {
            message.setActiveChat({ otherUser, product });
            const response = await http.get(
                `/api/message/messages/${user.user.id}/${otherUser.id}/${product ? product.id : 0}`
            );
            message.setMessages(response.data);
        } catch (error) {
            console.error('Ошибка при загрузке сообщений:', error);
        }
    };

    const sendMessage = async () => {
        if (!newMessage.trim() || !message.activeChat) return;

        setLoading(true);
        try {
            const messageData = {
                sender_id: user.user.id,
                receiver_id: message.activeChat.otherUser.id,
                product_id: message.activeChat.product?.id || null,
                message: newMessage.trim()
            };

            const response = await http.post('/api/message/send', messageData);
            message.addMessage(response.data);
            setNewMessage('');
            
            // Обновляем список чатов
            loadChats();
        } catch (error) {
            console.error('Ошибка при отправке сообщения:', error);
        } finally {
            setLoading(false);
        }
    };

    const handleKeyPress = (e) => {
        if (e.key === 'Enter' && !e.shiftKey) {
            e.preventDefault();
            sendMessage();
        }
    };

    return (
        <Modal 
            show={message.isModalOpen} 
            onHide={() => message.setIsModalOpen(false)}
            size="lg"
            centered
            dialogClassName="message-modal"
        >
            <Modal.Header closeButton>
                <Modal.Title>💬 Мои сообщения</Modal.Title>
            </Modal.Header>
            
            <Modal.Body className="message-modal-body">
                <Row>
                    {/* Список чатов */}
                    <Col md={4} className="chats-sidebar">
                        <div className="chats-header">
                            <h6>Чаты</h6>
                        </div>
                        {chatsLoading ? (
                            <div className="text-center p-3">
                                <Spinner animation="border" size="sm" />
                            </div>
                        ) : (
                            <ListGroup variant="flush" className="chats-list">
                                {message.chats.length > 0 ? (
                                    message.chats.map((chat, index) => (
                                        <ListGroup.Item
                                            key={index}
                                            action
                                            active={message.activeChat?.otherUser.id === chat.otherUser.id}
                                            onClick={() => loadMessages(chat.otherUser, chat.product)}
                                            className="chat-item"
                                        >
                                            <div className="chat-info">
                                                <div className="d-flex justify-content-between align-items-start">
                                                    <strong>{chat.otherUser.username}</strong>
                                                    {chat.unreadCount > 0 && (
                                                        <Badge bg="danger" pill className="ms-2">
                                                            {chat.unreadCount}
                                                        </Badge>
                                                    )}
                                                </div>
                                                {chat.product && (
                                                    <small className="text-muted d-block">
                                                        Товар: {chat.product.name}
                                                    </small>
                                                )}
                                                <small className="last-message text-muted">
                                                    {chat.lastMessage && (
                                                        chat.lastMessage.length > 30 
                                                            ? chat.lastMessage.substring(0, 30) + '...' 
                                                            : chat.lastMessage
                                                    )}
                                                </small>
                                                <small className="message-time d-block">
                                                    {chat.lastMessageTime && new Date(chat.lastMessageTime).toLocaleDateString()}
                                                </small>
                                            </div>
                                        </ListGroup.Item>
                                    ))
                                ) : (
                                    <ListGroup.Item>
                                        <div className="text-center text-muted py-3">
                                            Нет активных чатов
                                        </div>
                                    </ListGroup.Item>
                                )}
                            </ListGroup>
                        )}
                    </Col>

                    {/* Область сообщений */}
                    <Col md={8} className="messages-area">
                        {message.activeChat ? (
                            <>
                                <div className="chat-header">
                                    <h6 className="mb-0">
                                        Чат с {message.activeChat.otherUser.username}
                                        {message.activeChat.product && (
                                            <Badge bg="secondary" className="ms-2">
                                                {message.activeChat.product.name}
                                            </Badge>
                                        )}
                                    </h6>
                                    <small className="text-muted">
                                        {message.activeChat.otherUser.role === 'SELLER' ? 'Продавец' : 'Покупатель'}
                                    </small>
                                </div>
                                
                                <div className="messages-list">
                                    {message.messages.map((msg) => (
                                        <div
                                            key={msg.id}
                                            className={`message-bubble ${
                                                msg.sender_id === user.user.id ? 'sent' : 'received'
                                            }`}
                                        >
                                            <div className="message-content">
                                                {msg.message}
                                            </div>
                                            <small className="message-time">
                                                {new Date(msg.timestamp).toLocaleTimeString()}
                                            </small>
                                        </div>
                                    ))}
                                </div>

                                <div className="message-input">
                                    <Form.Group>
                                        <Form.Control
                                            as="textarea"
                                            rows={2}
                                            value={newMessage}
                                            onChange={(e) => setNewMessage(e.target.value)}
                                            onKeyPress={handleKeyPress}
                                            placeholder="Введите сообщение..."
                                            disabled={loading}
                                        />
                                    </Form.Group>
                                    <div className="d-flex justify-content-end mt-2">
                                        <Button
                                            variant="primary"
                                            onClick={sendMessage}
                                            disabled={!newMessage.trim() || loading}
                                            size="sm"
                                        >
                                            {loading ? 'Отправка...' : 'Отправить'}
                                        </Button>
                                    </div>
                                </div>
                            </>
                        ) : (
                            <div className="text-center text-muted select-chat-prompt">
                                <div className="py-5">
                                    <h6>Выберите чат для начала общения</h6>
                                    <small>или начните новый диалог с продавцом</small>
                                </div>
                            </div>
                        )}
                    </Col>
                </Row>
            </Modal.Body>
        </Modal>
    );
});

export default MessageModal;
